3. In app/(client)/client/home/page.tsx, replace the entire return JSX (the <> ... </> block that currently renders MaintenanceBanner + the full dashboard content + all modals). Keep the two Modal blocks (selectedCoach modal and showTicketModal modal) EXACTLY as they are — only the dashboard layout section before the modals changes. New JSX structure:

<>
  <MaintenanceBanner />

  <div className='space-y-6 sm:space-y-8'>
    {/* Page header — keep exactly as-is */}
    <PageHeader eyebrow='Client Console · San Jose del Monte, Bulacan' title={<>Welcome back, <span className='text-accent-text'>{user.firstname}</span></>} description='Book verified coaches, organize rehearsal sessions, and review digital session contracts.' action={<><Link href='/client/talent' className='inline-flex h-10 items-center justify-center gap-2 rounded-full bg-accent px-5 text-sm font-semibold tracking-[-0.01em] text-accent-foreground shadow-[var(--shadow-sm)] transition hover:bg-accent-hover hover:shadow-[var(--shadow-accent)]'><Sparkles className='h-4 w-4' aria-hidden /><span>Browse Coaches</span></Link><Button type='button' variant='outline' icon={<HelpCircle className='h-4 w-4' />} onClick={()=>setShowTicketModal(true)}>Support</Button></>} />

    {/* Quick actions */}
    <QuickActions actions={[{label:'Find Coach',href:'/client/talent',icon:<Sparkles className='h-4 w-4' />,variant:'primary'},{label:'Appointments',href:'/client/appointments',icon:<Calendar className='h-4 w-4' />},{label:'Calendar',href:'/client/calendar',icon:<CalendarDays className='h-4 w-4' />},{label:'Ask Groovey AI',href:'/client/groovey',icon:<Bot className='h-4 w-4' />},{label:'Messages',href:'/messages',icon:<MessageSquare className='h-4 w-4' />}]} />

    {/* Stat row */}
    <StatRow stats={[{value:upcomingAppointments.length,label:'Upcoming Sessions',description:'Scheduled appointments',icon:<Calendar className='h-5 w-5' />},{value:recommendedCoaches.length,label:'Verified Coaches',description:'Active in your region',icon:<BadgeCheck className='h-5 w-5' />},{value:'SJDM, Bulacan',label:'Platform Region',description:'Region III Hub',icon:<MapPin className='h-5 w-5' />},{value:<span className='flex items-center gap-2 text-2xl sm:text-3xl'><span className='h-2.5 w-2.5 shrink-0 rounded-full bg-success' aria-hidden />{' '}Verified Active</span>,label:'Account Status',description:`#${user.custom_id||'0001'}`,icon:<BadgeCheck className='h-5 w-5' />}]} />

    {/* Hero banner */}
    <HeroBanner eyebrow='San Jose del Monte Coaching Hub' headline='Elevate your performing arts craft' subline='Connect with top dance, vocal, theater, and instrument coaches. Secure your rehearsal slots with verifiable digital agreements.' primaryCta={{label:'Browse All Coaches',href:'/client/talent'}} secondaryCta={{label:'Studio Locator',href:'#studios'}} announcement={announcement} />

    {/* Main grid */}
    <div className='grid grid-cols-1 gap-5 lg:grid-cols-3 lg:gap-6'>
      <div className='space-y-5 lg:col-span-2 lg:space-y-6'>
        <CoachAvatarRow coaches={recommendedCoaches} viewAllHref='/client/talent' />
        <BadgeMiniWidget userId={user.id} role='client' />
        <SupportCallout onSubmitTicket={()=>setShowTicketModal(true)} />
      </div>
      <UpcomingSessionsWidget appointments={upcomingAppointments} perspective='client' viewAllHref='/client/appointments' />
    </div>

    {/* Studio locator — keep exactly as-is */}
    <StudioLocator id='studios' title='Rehearsal Studios Locator' subtitle='Performing arts spaces in San Jose del Monte and Bulacan — curated listings plus community-sourced results' />
  </div>

  {/* ALL MODAL JSX — keep exactly as-is: selectedCoach Modal and showTicketModal Modal */}
  {existing selectedCoach modal}
  {existing showTicketModal Modal}
</>

6. In app/(coach)/coach/home/page.tsx, replace the return JSX layout. Keep ProfileModal, TicketModal, MiniCalendar sub-components (defined inline above the CoachHomePage function) EXACTLY as-is — do not touch them. Keep selectedUser Modal and showTicket Modal EXACTLY as-is. New layout:

<div className='space-y-6 sm:space-y-7'>
  {/* Page header — keep exactly as-is (PageHeader with eyebrow, title using getGreeting(), action buttons) */}
  <PageHeader eyebrow='Coach Control Terminal' title={<>{getGreeting()}, <span className='text-accent-text'>Coach {coach.firstname}</span></>} description='Manage appointments, organize rehearsal sessions, and review performer requests in Bulacan.' action={<div className='flex flex-wrap items-center gap-2.5'><Link href='/coach/talents' className='inline-flex h-10 items-center justify-center gap-2 rounded-full bg-accent px-5 text-sm font-semibold tracking-[-0.01em] text-accent-foreground shadow-[var(--shadow-sm)] transition hover:-translate-y-0.5 hover:bg-accent-hover'><Sparkles className='h-4 w-4' aria-hidden /><span>Showcase Feed</span></Link><Link href='/messages' className='inline-flex h-10 items-center justify-center gap-2 rounded-full border border-border bg-card px-5 text-sm font-semibold tracking-[-0.01em] text-foreground transition hover:-translate-y-0.5 hover:border-border-strong hover:bg-muted'><Send className='h-3.5 w-3.5' aria-hidden /><span>Messages</span></Link></div>} />

  {/* Quick actions */}
  <QuickActions actions={[{label:'Showcase Feed',href:'/coach/talents',icon:<Sparkles className='h-4 w-4' />,variant:'primary'},{label:'Messages',href:'/messages',icon:<Send className='h-4 w-4' />},{label:'Calendar',href:'/coach/calendar',icon:<CalendarIcon className='h-4 w-4' />},{label:'Appointments',href:'/coach/appointments',icon:<CalendarIcon className='h-4 w-4' />}]} />

  {/* Stat row */}
  <StatRow stats={[{value:appointments.length,label:'Appointments',description:'Total session records',icon:<CalendarIcon className='h-5 w-5' />},{value:recommendedUsers.length,label:'Students in SJDM',description:'Registered performers',icon:<Users className='h-5 w-5' />},{value:<span className='text-2xl sm:text-3xl'>SJDM, Bulacan</span>,label:'Platform Region',description:'Region III',icon:<MapPin className='h-5 w-5' />},{value:<span className='flex items-center gap-2 text-xl sm:text-2xl'><span className='h-2.5 w-2.5 rounded-full bg-success' aria-hidden />Verified Active</span>,label:'Coach Status',description:`#${coach.custom_id||'0001'}`,icon:<CheckCircle2 className='h-5 w-5' />}]} />

  {/* Hero banner */}
  <HeroBanner eyebrow='Coach Instructor Workspace' headline='Inspire the next generation of performers' subline='Track session confirmations, negotiate digital coaching contracts, and connect with talents in Bulacan.' primaryCta={{label:'Community Showcase',href:'/coach/talents'}} secondaryCta={{label:'Manage Schedule',href:'/coach/appointments'}} announcement={announcement} />

  {/* Main 3-col grid */}
  <div className='grid grid-cols-1 gap-4 sm:gap-5 lg:grid-cols-3 lg:gap-6'>
    {/* 2-col main */}
    <div className='space-y-4 sm:space-y-5 lg:col-span-2'>
      <UpcomingSessionsWidget appointments={appointments} perspective='coach' viewAllHref='/coach/appointments' />
      <BadgeMiniWidget userId={coach.id} role='coach' />
      <SupportCallout onSubmitTicket={()=>setShowTicket(true)} />
    </div>

    {/* Sidebar */}
    <aside className='space-y-4 sm:space-y-5'>
      <MiniCalendar />

      {/* Students card — keep existing JSX for the student grid */}
      <Card padding='none'>
        <CardHeader className='mb-0 px-5 pb-4 sm:px-6 sm:pb-5' icon={<Users className='h-4 w-4' />} title='Students in San Jose del Monte' subtitle='Local performers looking for mentorship' />
        <div className='grid grid-cols-2 gap-3.5 px-5 pb-6 sm:px-6'>
          {recommendedUsers.slice(0,4).map(user => (/* keep exact existing JSX */)}
        </div>
      </Card>
    </aside>
  </div>

  {/* Studio locator — keep exactly as-is */}
  <StudioLocator title='Rehearsal Studios Directory' subtitle='Dance and performing arts studios around San Jose del Monte, Bulacan' padding='none' />
</div>

{selectedUser && <ProfileModal user={selectedUser} onClose={()=>setSelectedUser(null)} />}
{showTicket && <TicketModal coach={coach} onClose={()=>setShowTicket(false)} />}
